// Seven built-in textures plus 28 independently chosen solid colors fit in one
// base-36 character per surface (0 remains the inherited/default surface).
export const FIRST_SOLID_PAINT=7,MAX_SOLID_PAINTS=28,BUILDING_MATERIAL_LIMIT=35;
export function validatePaintColors(value){if(!Array.isArray(value)||value.length<1||value.length>MAX_SOLID_PAINTS||!Array.from(value).every(v=>typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v)))throw Error('Choose up to 28 solid paint colors.');return value.map(v=>v.toLowerCase());}
export function encodePaintMaterial(material){if(!Number.isInteger(material)||material<0||material>=BUILDING_MATERIAL_LIMIT)throw Error('Choose a valid paint material.');return (material+1).toString(36);}
export function decodePaintMaterial(code){if(typeof code!=='string'||code.length!==1||!/^[0-9a-z]$/.test(code))throw Error('Invalid surface paint entry.');return parseInt(code,36)-1;}
export function usedSolidPaints(design){const used=new Set();for(const id of design.materials||[])if(id>=FIRST_SOLID_PAINT)used.add(id-FIRST_SOLID_PAINT);for(const field of ['surfacePaint','groundPaint'])for(const code of design[field]||''){const id=decodePaintMaterial(code);if(id>=FIRST_SOLID_PAINT)used.add(id-FIRST_SOLID_PAINT);}return used;}
export function validatePaintReferences(design){const colors=design.paintColors===undefined?[]:validatePaintColors(design.paintColors);for(const id of usedSolidPaints(design))if(!Number.isInteger(id)||id<0||id>=colors.length)throw Error('Surface paint references a missing solid color.');return colors;}
export function chooseSolidPaint(design,color,reserved=[]){const normalized=validatePaintColors([color])[0],colors=design.paintColors===undefined?[]:validatePaintColors(design.paintColors);validatePaintReferences(design);let slot=colors.indexOf(normalized);if(slot<0){if(colors.length<MAX_SOLID_PAINTS){slot=colors.length;colors.push(normalized);}else{const used=usedSolidPaints(design);for(const index of reserved)used.add(index);slot=colors.findIndex((_,i)=>!used.has(i));if(slot<0)throw Error('All 28 solid colors are used by this model or its editing history. Apply and reopen after repainting unused colors.');colors[slot]=normalized;}}return{design:{...design,paintColors:colors},material:FIRST_SOLID_PAINT+slot};}
export function solidPaintColor(material,design){return material>=FIRST_SOLID_PAINT?design.paintColors?.[material-FIRST_SOLID_PAINT]:undefined;}
